# Navy "material duel" layout: navy bg, two tall product panels (pink / white) with a mint VS, side-by-side score rows, trap list, two-way verdict.
# Used for: Wooden vs plastic high chair (Nov 2026). Facts: NHS. Prices: BabySorted catalog.
import sys; sys.path.insert(0,__file__.rsplit('/',1)[0])
from extras import *
CSS=css(NAVY,"#fff",MINT,NAVY)+".n{color:#fff}"
deco=star(40,34,26,PINK)+star(1000,30,30,"#fff",.5)
TR=b("tripp.png",900); SN=b("snacker.png",900); IR=b("iris.png",700)
def panel(x,y,w,h,bg,pic,ph,label=None):
    l=f'<div style="position:absolute;left:0;right:0;bottom:22px;text-align:center"><span style="font-weight:800;font-size:30px;color:{NAVY};background:{"#fff" if bg==PINK else PINK};padding:8px 22px;border-radius:22px">{label}</span></div>' if label else ""
    return f'<div style="position:absolute;left:{x}px;top:{y}px;width:{w}px;height:{h}px;background:{bg};border-radius:40px;display:flex;align-items:center;justify-content:center;padding-bottom:{60 if label else 0}px"><img src="{pic}" style="height:{ph}px;max-width:{w-30}px;object-fit:contain;filter:drop-shadow(0 16px 16px rgba(5,31,69,.18))">{l}</div>'
def vs(x,y,s=110): return f'<div class="h" style="position:absolute;left:{x}px;top:{y}px;width:{s}px;height:{s}px;border-radius:50%;background:{MINT};color:{NAVY};display:flex;align-items:center;justify-content:center;font-size:{int(s*.4)}px;box-shadow:0 0 0 10px {NAVY}">VS</div>'
cover=star(640,330,30,PINK)+star(40,560,22,"#fff",.5)+f'''<div style="position:absolute;left:70px;right:70px;top:66px"><div class="tags"><span class="tag t1">Comparison</span><span class="tag t2">Kids Furniture</span></div>
<div class="h" style="font-size:88px;margin-top:26px;width:620px">Wooden vs plastic high chair: which is better?</div></div>
{round_pic(baby(11,310,380,.5,.42),710,50,310,380,44)}
<div style="position:absolute;left:70px;top:610px;width:940px;font-size:37px;font-weight:600;color:{PINK}">Style vs easy cleaning. Here's the honest answer.</div>
{panel(60,690,470,520,PINK,TR,440,"Wooden")}{panel(550,690,470,520,"#fff",SN,440,"Plastic")}{vs(485,890)}'''
def fact(n,t): return f'<div style="background:#fff;color:{NAVY};border-radius:34px;padding:30px 36px;margin-top:20px;display:flex;align-items:center;gap:30px"><div class="h" style="flex:none;width:270px;font-size:80px">{n}</div><div class="b" style="font-size:35px;line-height:1.3">{t}</div></div>'
s2=deco+f'''<div style="position:absolute;left:70px;right:70px;top:80px"><div class="kick" style="color:{PINK};opacity:1">BEFORE YOU PICK A SIDE</div><div class="h" style="font-size:84px;margin-top:10px">The material is not the safety test</div></div>
<div style="position:absolute;left:60px;right:60px;top:345px">{fact("Push","Give the chair a firm push from each side. It shouldn't rock or tip.")}{fact("Press","Lean on the seat and tray. Nothing should bend or creak.")}{fact("Fold","Open it and fold it. Look for gaps that could trap a finger.")}</div>
<div class="b" style="position:absolute;left:70px;right:70px;top:1020px;color:#fff;font-size:40px">Wood or plastic, a good chair has to pass these. So choose the material for your kitchen, not for safety.</div>'''
RW=[("Price","About £35 to £350","About £30 to £150"),("Cleaning","Wipes well, but check the joints","Smooth, but check the seat pad"),("Storing","Often stays out","Most fold flat"),("Lifespan","Can last for years","Often up to about 3")]
rw="".join(f'''<div style="padding:32px 0;border-top:{"0" if i==0 else f"3px solid {PINK}"}"><div style="font-weight:800;font-size:27px;letter-spacing:.05em;opacity:.5">{a.upper()}</div><div style="display:flex;gap:24px;margin-top:8px"><div class="h" style="flex:1;font-size:44px;line-height:1.15">{c}</div><div class="h" style="flex:1;font-size:44px;line-height:1.15">{d}</div></div></div>''' for i,(a,c,d) in enumerate(RW))
s3=deco+f'''<div style="position:absolute;left:70px;right:70px;top:70px"><div class="kick" style="color:{PINK};opacity:1">SIDE BY SIDE</div><div class="h" style="font-size:80px;margin-top:8px">What really changes</div></div>
<div style="position:absolute;left:60px;right:60px;top:240px;background:#fff;color:{NAVY};border-radius:40px;padding:26px 44px 16px"><div style="display:flex;gap:24px"><div style="flex:1"><span class="pill" style="background:{PINK}">Wooden</span></div><div style="flex:1"><span class="pill" style="background:{MINT}">Plastic</span></div></div><div style="margin-top:14px">{rw}</div></div>
<div style="position:absolute;left:70px;right:70px;top:1145px;font-size:27px;font-weight:600;opacity:.75;line-height:1.35">Prices on BabySorted, 6 Nov 2026. The ranges overlap, and some chairs cost more. Some wooden chairs fold too.</div>'''
def pick(kick,name,price,pic,h,bg,rows,watch,note):
    li="".join(f'<div class="b" style="font-size:37px;margin-top:12px;display:flex;gap:14px"><span style="color:{MINT};font-weight:800">✓</span><span>{r}</span></div>' for r in rows)
    return deco+f'''<div style="position:absolute;left:60px;right:60px;top:60px;height:650px;background:{bg};border-radius:44px;display:flex;align-items:center;justify-content:center"><img src="{pic}" style="height:580px;max-width:860px;object-fit:contain;filter:drop-shadow(0 18px 18px rgba(5,31,69,.18))"></div>
<div style="position:absolute;left:92px;top:90px"><span class="pill" style="background:{NAVY};color:#fff;font-size:27px">{kick}</span></div>
<div style="position:absolute;left:70px;right:70px;top:735px"><div style="display:flex;justify-content:space-between;align-items:baseline"><div class="h" style="font-size:62px">{name}</div><div class="h" style="font-size:62px;color:{MINT}">{price}</div></div>{li}
<div class="b" style="font-size:34px;margin-top:18px;color:{PINK}"><b style="font-weight:800">Watch out:</b> {watch}</div></div><div style="position:absolute;left:70px;right:70px;top:1190px;font-size:27px;font-weight:600;opacity:.7;">{note}</div>'''
s4=pick("The wooden pick","Stokke Tripp Trapp","£229",TR,540,PINK,["Seat and footplate both adjust as your child grows","Takes up to 136 kg, so it can last into adult life","No folding, so measure your table space first"],"a baby needs the Baby Set. Chair plus set is about £249.","Prices on BabySorted, 6 Nov 2026.")
s5=pick("The plastic pick","Joie Mimzy Snacker","£42.50",SN,540,"#fff",["One-hand fold, and it stands up when folded","Dishwasher-safe tray stores on the back legs","Three recline positions for a seat at this price"],"sit your baby upright to eat. The NHS says it helps them swallow.","Source: NHS. Price on BabySorted, 6 Nov 2026.")
TRP=[("Deep crevices","Squashed food gets stuck and stays there. Run a finger round the seat before you buy."),("Woven harness straps","Food stains are harder to shift from textured straps. Check they wipe clean or come off."),("A cover you can't wipe","Some wooden chairs have this too. Wood alone won't save you here.")]
tr="".join(f'''<div style="padding:38px 0;border-top:{"0" if i==0 else f"3px solid {PINK}"}"><div class="h" style="font-size:50px">{a}</div><div style="font-size:38px;font-weight:500;line-height:1.34;margin-top:10px">{c}</div></div>''' for i,(a,c) in enumerate(TRP))
s6=deco+f'''<div style="position:absolute;left:70px;right:70px;top:70px"><div class="kick" style="color:{PINK};opacity:1">THE 3PM CLEAN-UP</div><div class="h" style="font-size:80px;margin-top:8px">3 mess traps on any chair</div></div>
<div style="position:absolute;left:60px;right:60px;top:240px;background:#fff;color:{NAVY};border-radius:40px;padding:14px 44px 18px">{tr}</div>
<div style="position:absolute;left:70px;right:70px;top:1090px;font-size:35px;font-weight:600;color:{PINK}">Easy wins: a tray that lifts off, and navy or red seat pads that hide stains.</div>'''
CK=[("A fixed crotch strap","Trays can let a child slip under. Check for this strap even if the chair has a harness."),("A 5-point harness","Some chairs only have 3 points. The NHS says use a 5-point one every time."),("Feet can't push off","At the table, a child shouldn't be able to rock back. A wall behind them helps."),("No bite-off parts","Check padding, buckles and toy bars can't tear or come loose.")]
ck="".join(f'''<div style="display:flex;gap:24px;padding:24px 0;border-top:{"0" if i==0 else f"3px solid {PINK}"}"><div style="flex:none;width:60px;height:60px;border-radius:18px;background:{MINT};font-weight:800;font-size:32px;display:flex;align-items:center;justify-content:center">✓</div><div><div class="h" style="font-size:44px">{a}</div><div style="font-size:33px;font-weight:500;line-height:1.3;margin-top:6px">{c}</div></div></div>''' for i,(a,c) in enumerate(CK))
s7=deco+f'''<div style="position:absolute;left:70px;right:70px;top:70px"><div class="kick" style="color:{PINK};opacity:1">WHICHEVER YOU CHOOSE</div><div class="h" style="font-size:80px;margin-top:8px">4 checks in the shop</div></div>
<div style="position:absolute;left:60px;right:60px;top:240px;background:#fff;color:{NAVY};border-radius:40px;padding:12px 44px 14px">{ck}</div><div style="position:absolute;left:70px;right:70px;top:1070px;font-size:27px;font-weight:600;opacity:.7;">Source: NHS</div>'''
def side(t,bg,li,x,pic=""):
    r="".join(f'<div style="font-size:35px;font-weight:600;line-height:1.28;margin-top:16px">{i}</div>' for i in li)
    return f'<div style="position:absolute;left:{x}px;top:325px;width:470px;height:900px;background:{bg};color:{NAVY};border-radius:40px;padding:36px 34px"><div class="h" style="font-size:54px">{t}</div>{r}<div style="position:absolute;left:0;right:0;bottom:30px;display:flex;justify-content:center"><img src="{pic}" style="height:330px;filter:drop-shadow(0 14px 14px rgba(5,31,69,.16))"></div></div>'
s8=deco+f'''<div style="position:absolute;left:70px;right:70px;top:70px"><div class="kick" style="color:{PINK};opacity:1">THE HONEST ANSWER</div><div class="h" style="font-size:80px;margin-top:8px">Pick by your home, not the label</div></div>
{side("Go wooden if",PINK,["It will live at the table","You want it for years","A sibling may use it next","It suits the room"],60,IR)}{side("Go plastic if",MINT,["Your kitchen is small","It needs to fold away","Meals get very messy","Your budget is tight"],550,SN)}'''
s9=star(40,34,26,PINK)+f'''{round_pic(baby(4,960,590,.72,.45),60,60,960,590,44)}
<div style="position:absolute;left:70px;right:70px;top:680px"><div class="h" style="font-size:78px">Found your chair? Compare prices first</div>
<div class="b" style="margin-top:18px;font-size:38px">Compare high chair prices from UK shops in one place.</div>
<div style="margin-top:30px">{link_row(MINT)}</div>
<div style="margin-top:22px;font-size:32px;font-weight:700;opacity:.6">Save this post for later</div></div>'''
row=lambda a,c,d:f'<div style="display:flex;gap:16px;padding:16px 0;border-top:2px solid {PINK};align-items:center"><div style="flex:none;width:170px;font-weight:800;font-size:24px;opacity:.6">{a}</div><div class="h" style="flex:1;font-size:29px;line-height:1.15">{c}</div><div class="h" style="flex:1;font-size:29px;line-height:1.15">{d}</div></div>'
pin=f'''{star(910,50,30,PINK)}<div style="position:absolute;left:60px;right:60px;top:56px"><div class="tags"><span class="tag t1" style="font-size:24px">Comparison</span><span class="tag t2" style="font-size:24px">Kids Furniture</span></div>
<div class="h" style="font-size:78px;margin-top:20px">Wooden vs plastic high chair</div><div style="font-size:30px;font-weight:600;color:{PINK};margin-top:10px">Style vs easy cleaning. The honest answer.</div></div>
{panel(60,345,430,420,PINK,TR,370)}{panel(510,345,430,420,"#fff",SN,370)}{vs(445,500)}
<div style="position:absolute;left:60px;right:60px;top:785px;background:#fff;color:{NAVY};border-radius:30px;padding:16px 28px 14px"><div style="display:flex;gap:16px"><div style="flex:none;width:170px"></div><div class="h" style="flex:1;font-size:30px">Wooden</div><div class="h" style="flex:1;font-size:30px">Plastic</div></div>{"".join(row(a,c,d) for a,c,d in RW)}</div>
<div style="position:absolute;left:60px;right:60px;top:1225px;background:{MINT};color:{NAVY};border-radius:26px;padding:18px 26px"><div style="font-weight:800;font-size:22px;opacity:.7;letter-spacing:.06em">CHECK ON ANY CHAIR</div><div style="font-size:27px;font-weight:600;margin-top:4px;line-height:1.3">Fixed crotch strap. 5-point harness. Feet can't push off the table. No crevices. A tray that lifts off.</div></div>
<div style="position:absolute;left:60px;top:1382px;font-size:23px;font-weight:600;opacity:.75">Prices on BabySorted, 6 Nov 2026.</div>
<div style="position:absolute;left:60px;right:60px;bottom:38px;display:flex;justify-content:space-between;align-items:center"><div class="brand" style="font-size:34px">BabySorted</div><div style="font-weight:700;font-size:25px">Compare high chair prices at babysorted.com</div></div>'''
render(ROOT+"/out/p1",[cover,s2,s3,s4,s5,s6,s7,s8,s9],pin,CSS,"#fff")
